import React, { useState, useEffect } from 'react';
import MovieCard from '../components/MovieCard';

const SearchMovies = () => {
    const [searchTerm, setSearchTerm] = useState('');
    const [sortBy, setSortBy] = useState('default');
    const [movies, setMovies] = useState([]);
    const [loading, setLoading] = useState(false);

    // Sayfa ilk yüklendiğinde boş arama atarak varsayılan 20 filmi getir
    useEffect(() => {
        handleSearch('');
    }, []);

    const handleSearch = async (query) => {
        setLoading(true);
        try {
            const response = await fetch(`http://localhost:5000/api/movie/search?query=${query}`);
            const data = await response.json();
            setMovies(data);
        } catch (error) {
            console.error("Arama hatası:", error);
        } finally {
            setLoading(false);
        }
    };

    const onSubmit = (e) => {
        e.preventDefault();
        handleSearch(searchTerm);
    };

    return (
        <div style={{ padding: '40px', maxWidth: '1200px', margin: '0 auto' }}>
            <h1 style={{ borderBottom: '3px solid #17a2b8', paddingBottom: '10px' }}>🔍 Filmleri Keşfet</h1>

            <form onSubmit={onSubmit} style={{ display: 'flex', gap: '10px', marginTop: '20px', marginBottom: '40px' }}>
                <input
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Film adı veya türü (Örn: Aksiyon, Matrix, Avatar)..."
                    style={{ flex: 1, padding: '12px', fontSize: '16px', borderRadius: '5px', border: '1px solid #ccc' }}
                />
                <button type="submit" style={styles.button}>Ara</button>
            </form>

            {loading ? (
                <div style={{ textAlign: 'center', fontSize: '18px' }}>Aranıyor...</div>
            ) : (
                <div style={styles.grid}>
                    {movies.length > 0 ? (
                        movies.map(movie => <MovieCard key={movie.id} movie={movie} />)
                    ) : (
                        <p style={{ gridColumn: '1 / -1', textAlign: 'center' }}>Aradığınız kritere uygun film bulunamadı.</p>
                    )}
                </div>
            )}
        </div>
    );
};

const styles = {
    button: {
        padding: '12px 24px',
        fontSize: '16px',
        backgroundColor: '#17a2b8',
        color: '#fff',
        border: 'none',
        borderRadius: '5px',
        cursor: 'pointer',
        fontWeight: 'bold'
    },
    grid: {
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
        gap: '20px'
    }
};

export default SearchMovies;
